import { useState } from 'react'
import ShoeArt from './ShoeArt.jsx'

// Carousel following the APG carousel pattern: one slide visible at a time,
// previous/next buttons, wrapping from the last photo back to the first.
export default function Gallery({ photos, productName, colorName, colorHex }) {
  const [index, setIndex] = useState(0)
  const count = photos.length
  const photo = photos[index]
  const slideId = 'gallery-slide'
  const position = `${index + 1} of ${count}`

  const go = (step) => setIndex((i) => (i + step + count) % count)

  return (
    <section className="gallery" aria-roledescription="carousel" aria-label={`${productName} photos`}>
      <div className="slide" id={slideId} role="group" aria-roledescription="slide" aria-label={`${position}: ${photo.label}`}>
        <ShoeArt view={photo.id} color={colorHex} label={`${productName} in ${colorName}, ${photo.label.toLowerCase()}`} />
      </div>
      <div className="gallery-controls">
        <button type="button" className="icon-button" aria-controls={slideId} onClick={() => go(-1)}>
          <span aria-hidden="true">←</span>
          <span className="visually-hidden">Previous photo</span>
        </button>
        <span className="counter" aria-hidden="true">{index + 1} / {count}</span>
        <button type="button" className="icon-button" aria-controls={slideId} onClick={() => go(1)}>
          <span aria-hidden="true">→</span>
          <span className="visually-hidden">Next photo</span>
        </button>
      </div>
      <p className="visually-hidden" aria-live="polite">{`Photo ${position}: ${photo.label}`}</p>
    </section>
  )
}
