import { useEffect, useRef, useState } from 'react'

function Swatch({ hex }) {
  return <span className="swatch" style={{ backgroundColor: hex }} aria-hidden="true" />
}

// Shows only the chosen colour. Activating it opens a radio group (APG radio
// group pattern: arrow keys move and select, one tab stop). Choosing or
// pressing Escape closes the group.
export default function ColorPicker({ colors, value, onChange }) {
  const [open, setOpen] = useState(false)
  const [focusIndex, setFocusIndex] = useState(0)
  const toggleRef = useRef(null)
  const radioRefs = useRef([])
  const current = colors.find((c) => c.id === value)
  const checkedIndex = colors.findIndex((c) => c.id === value)

  useEffect(() => {
    if (open) radioRefs.current[checkedIndex]?.focus()
  }, [open, checkedIndex])

  function openGroup() {
    setFocusIndex(checkedIndex)
    setOpen(true)
  }

  function closeGroup() {
    setOpen(false)
    toggleRef.current?.focus()
  }

  function select(index) {
    onChange(colors[index].id)
  }

  function onRadioKeyDown(event, index) {
    let next = null
    if (event.key === 'ArrowRight' || event.key === 'ArrowDown') next = (index + 1) % colors.length
    if (event.key === 'ArrowLeft' || event.key === 'ArrowUp') next = (index - 1 + colors.length) % colors.length
    if (event.key === 'Home') next = 0
    if (event.key === 'End') next = colors.length - 1
    if (event.key === 'Escape') {
      event.preventDefault()
      closeGroup()
      return
    }
    if (next !== null) {
      event.preventDefault()
      setFocusIndex(next)
      select(next)
      radioRefs.current[next]?.focus()
    }
  }

  return (
    <div className="field">
      <div className="field-label-row">
        <span id="color-label" className="field-label">Color</span>
      </div>
      <div className="disclosure">
        <button
          ref={toggleRef}
          type="button"
          id="color-toggle"
          className="select-button"
          aria-expanded={open}
          aria-controls="color-options"
          aria-labelledby="color-label color-toggle"
          onClick={() => (open ? closeGroup() : openGroup())}
        >
          <Swatch hex={current.hex} />
          <span>{current.name}</span>
          <span className="chevron" aria-hidden="true">{open ? '▴' : '▾'}</span>
        </button>
        {open && (
          <div
            id="color-options"
            role="radiogroup"
            aria-labelledby="color-label"
            className="options-panel color-options"
          >
            {colors.map((color, index) => {
              const checked = color.id === value
              return (
                <button
                  key={color.id}
                  ref={(el) => (radioRefs.current[index] = el)}
                  type="button"
                  role="radio"
                  aria-checked={checked}
                  aria-label={color.name}
                  tabIndex={index === focusIndex ? 0 : -1}
                  className={`color-option${checked ? ' is-checked' : ''}`}
                  onClick={() => {
                    select(index)
                    closeGroup()
                  }}
                  onKeyDown={(event) => onRadioKeyDown(event, index)}
                  onFocus={() => setFocusIndex(index)}
                >
                  <Swatch hex={color.hex} />
                  <span>{color.name}</span>
                </button>
              )
            })}
          </div>
        )}
      </div>
    </div>
  )
}
