import { useEffect, useRef, useState } from 'react'

// Shows only the chosen size. Activating it opens a listbox (APG listbox
// pattern). Sold-out sizes are listed as aria-disabled and cannot be chosen.
export default function SizePicker({ rows, value, onChange, error, errorId, onOpenGuide, guideRef, buttonRef }) {
  const [open, setOpen] = useState(false)
  const [active, setActive] = useState(0)
  const listRef = useRef(null)
  const wrapRef = useRef(null)
  const optionRefs = useRef([])

  const selectedIndex = rows.findIndex((r) => r.us === value)

  useEffect(() => {
    if (open) listRef.current?.focus()
  }, [open])

  useEffect(() => {
    if (open) optionRefs.current[active]?.scrollIntoView?.({ block: 'nearest' })
  }, [open, active])

  // Close when the pointer is pressed outside the picker.
  useEffect(() => {
    if (!open) return
    function onPointerDown(event) {
      if (!wrapRef.current?.contains(event.target)) setOpen(false)
    }
    document.addEventListener('pointerdown', onPointerDown)
    return () => document.removeEventListener('pointerdown', onPointerDown)
  }, [open])

  function openList() {
    const firstAvailable = rows.findIndex((r) => !r.soldOut)
    setActive(selectedIndex >= 0 ? selectedIndex : firstAvailable)
    setOpen(true)
  }

  function closeList(returnFocus = true) {
    setOpen(false)
    if (returnFocus) buttonRef.current?.focus()
  }

  function choose(index) {
    if (rows[index].soldOut) return
    onChange(rows[index].us)
    closeList()
  }

  function onButtonKeyDown(event) {
    if (event.key === 'ArrowDown' || event.key === 'ArrowUp') {
      event.preventDefault()
      openList()
    }
  }

  function onListKeyDown(event) {
    switch (event.key) {
      case 'ArrowDown':
        event.preventDefault()
        setActive((i) => Math.min(rows.length - 1, i + 1))
        break
      case 'ArrowUp':
        event.preventDefault()
        setActive((i) => Math.max(0, i - 1))
        break
      case 'Home':
        event.preventDefault()
        setActive(0)
        break
      case 'End':
        event.preventDefault()
        setActive(rows.length - 1)
        break
      case 'Enter':
      case ' ':
        event.preventDefault()
        choose(active)
        break
      case 'Escape':
        event.preventDefault()
        closeList()
        break
      case 'Tab':
        event.preventDefault()
        closeList()
        break
      default:
    }
  }

  const describedBy = [errorId && error ? errorId : null].filter(Boolean).join(' ') || undefined

  return (
    <div className="field" ref={wrapRef}>
      <div className="field-label-row">
        <span id="size-label" className="field-label">Size</span>
        <button type="button" className="link-button" onClick={onOpenGuide} ref={guideRef}>
          Size guide
        </button>
      </div>
      <div className="disclosure">
        <button
          ref={buttonRef}
          type="button"
          id="size-toggle"
          className={`select-button${error ? ' is-error' : ''}`}
          aria-haspopup="listbox"
          aria-expanded={open}
          aria-controls={open ? 'size-options' : undefined}
          aria-labelledby="size-label size-toggle"
          aria-describedby={describedBy}
          onClick={() => (open ? closeList() : openList())}
          onKeyDown={onButtonKeyDown}
        >
          <span>{value ? `US ${value}` : 'Select a size'}</span>
          <span className="chevron" aria-hidden="true">{open ? '▴' : '▾'}</span>
        </button>
        {open && (
          <ul
            ref={listRef}
            id="size-options"
            role="listbox"
            tabIndex={-1}
            aria-labelledby="size-label"
            aria-activedescendant={`size-option-${active}`}
            className="options-panel size-options"
            onKeyDown={onListKeyDown}
          >
            {rows.map((row, index) => {
              const selected = row.us === value
              return (
                <li
                  key={row.us}
                  id={`size-option-${index}`}
                  ref={(el) => (optionRefs.current[index] = el)}
                  role="option"
                  aria-selected={selected}
                  aria-disabled={row.soldOut ? 'true' : undefined}
                  className={[
                    'size-option',
                    index === active ? 'is-active' : '',
                    row.soldOut ? 'is-sold-out' : '',
                  ].join(' ')}
                  onMouseDown={(e) => e.preventDefault()}
                  onClick={() => choose(index)}
                >
                  <span>US {row.us}</span>
                  <span className="size-eu">EU {row.eu}</span>
                  {row.soldOut && <span className="sold-out-label">Sold out</span>}
                  {selected && <span className="visually-hidden"> (selected)</span>}
                </li>
              )
            })}
          </ul>
        )}
      </div>
      {error && (
        <p id={errorId} className="field-error">{error}</p>
      )}
    </div>
  )
}
