// Quantity: typed number, or one-step buttons. Valid values are whole numbers 1 to max.
export function parseQuantity(text, max) {
  const trimmed = String(text).trim()
  if (trimmed === '') return null
  const n = Number(trimmed)
  return Number.isInteger(n) && n >= 1 && n <= max ? n : null
}

export default function QuantityField({ value, max, onChange, error, inputRef }) {
  const parsed = parseQuantity(value, max)
  const step = (delta) => {
    const base = parsed ?? 1
    onChange(String(Math.min(max, Math.max(1, base + delta))))
  }

  return (
    <div className="field">
      <label htmlFor="quantity" className="field-label">Quantity</label>
      <div className="stepper">
        <button
          type="button"
          className="stepper-button"
          aria-label="Decrease quantity"
          onClick={() => step(-1)}
          disabled={parsed === 1}
        >
          −
        </button>
        <input
          ref={inputRef}
          id="quantity"
          type="number"
          inputMode="numeric"
          min="1"
          max={max}
          step="1"
          value={value}
          aria-invalid={error ? 'true' : undefined}
          aria-describedby={error ? 'quantity-error' : undefined}
          onChange={(e) => onChange(e.target.value)}
        />
        <button
          type="button"
          className="stepper-button"
          aria-label="Increase quantity"
          onClick={() => step(1)}
          disabled={parsed === max}
        >
          +
        </button>
      </div>
      {error && (
        <p id="quantity-error" className="field-error">
          Enter a whole number from 1 to {max}.
        </p>
      )}
    </div>
  )
}
