import { useEffect, useId, useRef, useState } from 'react'

const FOCUSABLE =
  'a[href], button:not([disabled]), input:not([disabled]), select:not([disabled]), textarea:not([disabled]), [tabindex]:not([tabindex="-1"])'

// Foot length (cm) -> the smallest size whose length fits, skipping sold-out sizes
// when possible. Returns { exact, recommended, length } or an error string.
export function recommendSize(rows, lengthCm) {
  if (!Number.isFinite(lengthCm) || lengthCm < 20 || lengthCm > 35) {
    return { error: 'Enter a foot length between 20 and 35 cm.' }
  }
  const exact = rows.find((r) => r.cm >= lengthCm)
  if (!exact) return { error: 'That length is longer than our largest size. Check the measurement.' }
  const recommended = rows.find((r) => r.cm >= lengthCm && !r.soldOut) ?? exact
  return { exact, recommended }
}

// Modal size guide (APG modal dialog pattern): focus moves into the dialog, Tab
// is trapped inside, Escape closes, and focus returns to the trigger on close.
// The page behind is made inert by the parent while this is open.
export default function SizeGuideDialog({ rows, returnRef, onClose, onUseSize }) {
  const dialogRef = useRef(null)
  const lengthRef = useRef(null)
  const titleId = useId()
  const descId = useId()
  const [lengthText, setLengthText] = useState('')
  const [system, setSystem] = useState('US')
  const [lengthError, setLengthError] = useState(null)
  const [result, setResult] = useState(null)

  useEffect(() => {
    lengthRef.current?.focus()
    const returnTo = returnRef
    return () => returnTo.current?.focus()
  }, [returnRef])

  function onSubmit(event) {
    event.preventDefault()
    const length = Number(lengthText)
    const outcome = recommendSize(rows, length)
    if (outcome.error) {
      setLengthError(outcome.error)
      setResult(null)
      lengthRef.current?.focus()
      return
    }
    setLengthError(null)
    setResult({ ...outcome, system })
  }

  function onKeyDown(event) {
    if (event.key === 'Escape') {
      event.preventDefault()
      onClose()
      return
    }
    if (event.key !== 'Tab') return
    const items = [...dialogRef.current.querySelectorAll(FOCUSABLE)].filter((el) => el.offsetParent !== null)
    if (items.length === 0) return
    const first = items[0]
    const last = items[items.length - 1]
    if (event.shiftKey && document.activeElement === first) {
      event.preventDefault()
      last.focus()
    } else if (!event.shiftKey && document.activeElement === last) {
      event.preventDefault()
      first.focus()
    }
  }

  const label = (row) => (result?.system === 'EU' ? `EU ${row.eu} (US ${row.us})` : `US ${row.us} (EU ${row.eu})`)

  return (
    <div className="modal-backdrop">
      <div
        ref={dialogRef}
        role="dialog"
        aria-modal="true"
        aria-labelledby={titleId}
        aria-describedby={descId}
        className="modal"
        onKeyDown={onKeyDown}
