import { useRef, useState } from 'react'

// Details, reviews and shipping as tabs (APG tabs pattern with automatic
// activation). Only the selected panel is shown.
export default function MoreInfo({ info }) {
  const tabs = [
    { id: 'details', label: 'Details' },
    { id: 'reviews', label: 'Reviews' },
    { id: 'shipping', label: 'Shipping & returns' },
  ]
  const [selected, setSelected] = useState('details')
  const tabRefs = useRef({})

  function activate(id) {
    setSelected(id)
    tabRefs.current[id]?.focus()
  }

  function onKeyDown(event, index) {
    let nextIndex = null
    if (event.key === 'ArrowRight') nextIndex = (index + 1) % tabs.length
    if (event.key === 'ArrowLeft') nextIndex = (index - 1 + tabs.length) % tabs.length
    if (event.key === 'Home') nextIndex = 0
    if (event.key === 'End') nextIndex = tabs.length - 1
    if (nextIndex !== null) {
      event.preventDefault()
      activate(tabs[nextIndex].id)
    }
  }

  return (
    <section className="more-info" aria-labelledby="more-info-title">
      <h2 id="more-info-title">More information</h2>
      <div role="tablist" aria-label="More information sections" className="tablist">
        {tabs.map((tab, index) => (
          <button
            key={tab.id}
            ref={(el) => (tabRefs.current[tab.id] = el)}
            type="button"
            role="tab"
            id={`tab-${tab.id}`}
            aria-selected={selected === tab.id}
            aria-controls={`panel-${tab.id}`}
            tabIndex={selected === tab.id ? 0 : -1}
            className="tab"
            onClick={() => setSelected(tab.id)}
            onKeyDown={(e) => onKeyDown(e, index)}
          >
            {tab.label}
          </button>
        ))}
      </div>

      <div id="panel-details" role="tabpanel" aria-labelledby="tab-details" hidden={selected !== 'details'} tabIndex={0} className="tabpanel">
        <ul className="plain-list">
          {info.details.map((item) => <li key={item}>{item}</li>)}
        </ul>
      </div>

      <div id="panel-reviews" role="tabpanel" aria-labelledby="tab-reviews" hidden={selected !== 'reviews'} tabIndex={0} className="tabpanel">
        <p><strong>{info.reviews.summary}</strong></p>
        {info.reviews.items.map((review) => (
          <article key={review.title} className="review">
            <h3>{review.title}</h3>
            <p className="review-meta">
              {review.rating} out of 5 stars, by {review.name}
            </p>
            <p>{review.body}</p>
          </article>
