  text-align: left;
  color: var(--ink);
  cursor: pointer;
}
.color-option:hover { background: var(--surface); }
.color-option.is-checked { border-color: var(--ink); font-weight: 600; }

.size-options { padding: 4px; }
.size-option {
  display: flex;
  align-items: center;
  gap: 12px;
  min-height: 44px;
  padding: 8px 10px;
  border-radius: 4px;
  cursor: pointer;
}
.size-option[aria-selected="true"] { font-weight: 700; }
.size-option.is-active { background: #e6edf7; outline: 2px solid var(--primary); outline-offset: -2px; }
.size-option.is-sold-out { color: var(--muted); }
.size-option.is-sold-out > span:first-child { text-decoration: line-through; }
.size-eu { color: var(--muted); font-size: 0.9rem; }
.sold-out-label { margin-left: auto; font-size: 0.85rem; font-style: italic; }

/* Quantity */
.stepper { display: inline-flex; align-items: stretch; width: max-content; }
.stepper-button {
  width: 44px;
  min-height: 44px;
  border: 1px solid var(--field-border);
  background: #fff;
  font: inherit;
  font-size: 1.2rem;
  cursor: pointer;
  color: var(--ink);
}
.stepper-button:disabled { color: var(--muted); cursor: not-allowed; background: var(--surface); }
.stepper input {
  width: 72px;
  min-height: 44px;
  text-align: center;
  font: inherit;
  border: 1px solid var(--field-border);
  border-left: 0;
  border-right: 0;
  padding: 0 8px;
  color: var(--ink);
  background: #fff;
}
.stepper input[aria-invalid="true"] { border-color: var(--error); border-width: 2px; }

/* Inputs */
input[type="number"], .size-finder input[type="number"] {
  min-height: 44px;
  padding: 8px 12px;
  font: inherit;
  border: 1px solid var(--field-border);
  border-radius: 6px;
  color: var(--ink);
  background: #fff;
  max-width: 200px;
}
input[aria-invalid="true"] { border-color: var(--error); border-width: 2px; }

/* Buttons */
.button-primary,
.button-secondary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  min-height: 48px;
  padding: 10px 20px;
  border-radius: 999px;
  font: inherit;
  font-weight: 600;
  cursor: pointer;
  text-decoration: none;
}
.button-primary { background: var(--primary); color: #fff; border: 2px solid var(--primary); }
.button-primary:hover { background: var(--primary-hover); color: #fff; }
.button-secondary { background: #fff; color: var(--ink); border: 2px solid var(--ink); }
.button-secondary:hover { background: var(--surface); color: var(--ink); }
.button-wide { width: 100%; }
.actions { display: flex; flex-direction: column; gap: 10px; }
.wishlist-button { width: 100%; }
.wishlist-button[aria-pressed="true"] { background: var(--surface); }

.confirmation p { margin: 0; padding: 12px 14px; background: var(--surface); border-radius: 6px; }
.confirmation:empty { display: none; }

/* More information tabs */
.more-info, .questions { max-width: 1280px; margin: 0 auto; padding: 24px; }
.more-info h2, .questions h2 { font-size: 1.4rem; margin-bottom: 12px; }
.tablist {
  display: flex;
  flex-wrap: wrap;
  border-bottom: 1px solid var(--field-border);
  margin-bottom: 16px;
}
.tab {
  min-height: 48px;
  padding: 10px 16px;
  background: none;
  border: 0;
  border-bottom: 3px solid transparent;
  margin-bottom: -1px;
  font: inherit;
  color: var(--muted);
  cursor: pointer;
}
.tab[aria-selected="true"] { color: var(--ink); font-weight: 700; border-bottom-color: var(--ink); }
.tabpanel { padding: 8px 0; max-width: 72ch; }
.plain-list { list-style: none; margin: 0; padding: 0; }
.plain-list li { padding: 4px 0; }
.review { border-top: 1px solid var(--line); padding: 12px 0; }
.review h3 { font-size: 1.05rem; margin-bottom: 4px; }
.review-meta { color: var(--muted); font-size: 0.9rem; }

/* Questions accordion */
.faq-item { border-bottom: 1px solid var(--field-border); }
.faq-heading { font-size: 1.05rem; }
.faq-button {
  width: 100%;
  min-height: 52px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 16px;
  padding: 12px 0;
  background: none;
  border: 0;
  font: inherit;
  font-weight: 600;
  text-align: left;
  color: var(--ink);
  cursor: pointer;
}
.faq-answer { padding: 0 0 16px; max-width: 72ch; }

/* Modal size guide */
.modal-backdrop {
  position: fixed;
  inset: 0;
  z-index: 100;
  background: rgba(0, 0, 0, 0.6);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
}
.modal {
  background: #fff;
  color: var(--ink);
  width: 100%;
  max-width: 640px;
  max-height: calc(100vh - 32px);
  overflow-y: auto;
  border-radius: 10px;
  padding: 24px;
  display: flex;
  flex-direction: column;
  gap: 16px;
}
.modal-header { display: flex; justify-content: space-between; align-items: center; gap: 12px; }
.modal-header h2 { font-size: 1.4rem; }
.size-table { border-collapse: collapse; width: 100%; font-size: 0.95rem; }
.size-table caption { text-align: left; font-weight: 600; margin-bottom: 6px; }
.size-table th, .size-table td { border: 1px solid var(--line); padding: 6px 10px; text-align: left; }
.size-table thead th { background: var(--surface); }
.size-finder { display: flex; flex-direction: column; gap: 16px; }
.size-finder fieldset { border: 0; padding: 0; margin: 0; }
.size-finder legend { padding: 0; margin-bottom: 6px; font-weight: 600; }
.radio-row { display: flex; gap: 20px; }
.radio-label { display: inline-flex; align-items: center; gap: 8px; min-height: 44px; }
.radio-label input { width: 20px; height: 20px; accent-color: var(--primary); }
.size-finder .button-primary { align-self: flex-start; }
.size-result { min-height: 0; display: flex; flex-direction: column; gap: 12px; }
.size-result:empty { display: none; }
.size-result p { margin: 0; }
.size-result .button-primary { align-self: flex-start; }

/* Footer */
.site-footer { background: var(--surface); margin-top: 32px; padding: 32px 24px 24px; }
.footer-grid {
  max-width: 1280px;
  margin: 0 auto;
  display: grid;
  gap: 28px;
  grid-template-columns: 1fr;
}
@media (min-width: 700px) {
  .footer-grid { grid-template-columns: repeat(3, 1fr); }
}
.site-footer h2 { font-size: 1rem; margin-bottom: 10px; }
.site-footer a { display: inline-flex; align-items: center; min-height: 32px; }
.copyright { max-width: 1280px; margin: 28px auto 0; font-size: 0.875rem; color: var(--muted); }

/* Narrow screens (reflow to 320px) */
@media (max-width: 480px) {
  .site-header-inner { padding: 12px 16px; }
  .cart-link { margin-left: 0; }
  .product-layout, .more-info, .questions { padding: 16px; }
  .modal { padding: 16px; }
}

@media (prefers-reduced-motion: reduce) {
  * { transition: none !important; animation: none !important; }
}
